// Sample messages. Replace this node with your real trigger
// (Webhook, Gmail, Chatwoot, Zendesk, etc) and map the text to `message`.
// One per routing tier, measured against the banking77 task used below:
//   clear intent        -> auto-route
//   vague but in scope  -> suggest and confirm
//   thin margin         -> manual review
//   not banking at all  -> out of scope
const messages = [
  "I was charged twice for my last transaction",
  "My card is about to expire, how do I renew it?",
  "it is broken again",
  "What currencies does the app support?",
  "I would like to apply for a job at your company"
];
const pick = messages[Math.floor(Math.random() * messages.length)];
return [{ json: { message: pick } }];

// Three-tier confidence routing.
// Jeffy returns: label, confidence, margin, out_of_scope, probabilities,
// plus best_guess when the threshold rejects the top label.
// Keep the node's Confidence Threshold option BELOW SUGGEST (it is 0.3 here),
// otherwise the server marks everything under SUGGEST out_of_scope and the
// manual-review tier can never fire.
const AUTO = 0.8;        // auto-route at or above this confidence
const SUGGEST = 0.5;     // suggest-and-confirm between SUGGEST and AUTO
const MIN_MARGIN = 0.15; // top-two gap below this means it is a close call

// The Jeffy node returns one result per input item, in order, so index pairing holds.
return $input.all().map((item, i) => {
  const r = item.json;
  const source = $('Incoming Message').all()[i];
  const message = source ? source.json.message : null;

  let tier;
  if (r.out_of_scope) {
    tier = 'out_of_scope';
  } else if (r.confidence >= AUTO && (r.margin ?? 1) >= MIN_MARGIN) {
    tier = 'auto';
  } else if (r.confidence >= SUGGEST) {
    tier = 'suggest';
  } else {
    tier = 'review';
  }

  return {
    json: {
      message,
      tier,
      label: r.label,
      confidence: r.confidence,
      margin: r.margin,
      best_guess: r.best_guess ?? null,
      top_alternatives: Object.entries(r.probabilities || {}).slice(0, 3)
    }
  };
});
